#define MOD 1000000007LL

/*
The statement shown here is incomplete, so we implement the standard solution for:
count strings over {A,T,G,C} with exact counts (Na,Nt,Ng,Nc) generated by a context-free
grammar given by non-terminals and productions.

Assumed input format:
N M S
Na Nt Ng Nc
Then M productions, each in the form:
X -> rhs
where X is a single uppercase non-terminal letter, and rhs is a string of symbols
consisting of terminals A,T,G,C and uppercase non-terminals.
Spaces are allowed.

N = number of non-terminals (not strictly needed if symbols are implicit)
M = number of productions
S = start non-terminal (single uppercase letter)

If your judge uses a slightly different but equivalent format, only the parser may need
adjustment; the DP core is grammar-based counting by exact terminal multiplicities.

Method:
For each non-terminal X, dp[X][a][t][g][c] = number of strings derivable from X with
exactly those terminal counts.

For a production X -> Y1 Y2 ... Yk, we evaluate the generating count table of the sequence
by convolution over 4 dimensions, where a terminal contributes one unit in its dimension,
and a non-terminal contributes according to its own dp table.

Since grammar may be recursive, we compute a least fixed point by repeated relaxation.
This works for acyclic grammars directly; for recursive grammars that generate finitely many
strings under bounded counts, it converges because all states are bounded by counts.

This is practical only for small counts, which is the standard intended setting for such tasks.
*/

typedef struct {
    char lhs;
    char rhs[256];
    int len;
} Rule;

static long long *dp[26];
static int SA, ST, SG, SC;
static int SZ;
static Rule *rules;
static int M;

static inline int idx4(int a, int t, int g, int c) {
    return (((a * (ST + 1) + t) * (SG + 1) + g) * (SC + 1) + c);
}

static void addmod(long long *x, long long v) {
    *x += v;
    if (*x >= MOD) *x %= MOD;
}

static void trim_line(char *s) {
    int n = (int)strlen(s);
    while (n > 0 && (s[n-1] == '\n' || s[n-1] == '\r')) s[--n] = 0;
}

static int is_nt(char ch) {
    return ch >= 'A' && ch <= 'Z' && ch != 'A' && ch != 'T' && ch != 'G' && ch != 'C';
}

static int nt_id(char ch) {
    return ch - 'A';
}

static void build_symbol_table(char sym, long long *out) {
    memset(out, 0, sizeof(long long) * SZ);
    if (sym == 'A') {
        if (SA >= 1) out[idx4(1,0,0,0)] = 1;
    } else if (sym == 'T') {
        if (ST >= 1) out[idx4(0,1,0,0)] = 1;
    } else if (sym == 'G') {
        if (SG >= 1) out[idx4(0,0,1,0)] = 1;
    } else if (sym == 'C') {
        if (SC >= 1) out[idx4(0,0,0,1)] = 1;
    } else {
        memcpy(out, dp[nt_id(sym)], sizeof(long long) * SZ);
    }
}

static int relax_rule(const Rule *r, long long *target_new) {
    long long *cur = (long long *)calloc(SZ, sizeof(long long));
    long long *nxt = (long long *)calloc(SZ, sizeof(long long));
    long long *tab = (long long *)calloc(SZ, sizeof(long long));
    int changed = 0;

    cur[idx4(0,0,0,0)] = 1;

    for (int pos = 0; pos < r->len; pos++) {
        build_symbol_table(r->rhs[pos], tab);
        memset(nxt, 0, sizeof(long long) * SZ);

        for (int a1 = 0; a1 <= SA; a1++) {
            for (int t1 = 0; t1 <= ST; t1++) {
                for (int g1 = 0; g1 <= SG; g1++) {
                    for (int c1 = 0; c1 <= SC; c1++) {
                        long long v1 = cur[idx4(a1,t1,g1,c1)];
                        if (!v1) continue;
                        for (int a2 = 0; a2 + a1 <= SA; a2++) {
                            for (int t2 = 0; t2 + t1 <= ST; t2++) {
                                for (int g2 = 0; g2 + g1 <= SG; g2++) {
                                    for (int c2 = 0; c2 + c1 <= SC; c2++) {
                                        long long v2 = tab[idx4(a2,t2,g2,c2)];
                                        if (!v2) continue;
                                        int id = idx4(a1+a2, t1+t2, g1+g2, c1+c2);
                                        nxt[id] = (nxt[id] + v1 * v2) % MOD;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        long long *tmp = cur; cur = nxt; nxt = tmp;
    }

    int lhs = nt_id(r->lhs);
    for (int i = 0; i < SZ; i++) {
        long long oldv = target_new[i];
        long long nv = oldv + cur[i];
        if (nv >= MOD) nv %= MOD;
        if (nv != oldv) changed = 1;
        target_new[i] = nv;
    }

    free(cur);
    free(nxt);
    free(tab);
    return changed;
}

