import java.util.*;
import java.math.*;

public class Main {
    static final long MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long Na = sc.nextLong();
        long Nt = sc.nextLong();
        long Ng = sc.nextLong();
        long Nc = sc.nextLong();

        long n = Na + Nt + Ng + Nc;
        // Compute multinomial coefficient n! / (Na! * Nt! * Ng! * Nc!)
        long[] fact = new long[(int)(n + 1)];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i-1] * i % MOD;
        }

        long ans = fact[(int)n];
        ans = ans * modInverse(fact[(int)Na], MOD) % MOD;
        ans = ans * modInverse(fact[(int)Nt], MOD) % MOD;
        ans = ans * modInverse(fact[(int)Ng], MOD) % MOD;
        ans = ans * modInverse(fact[(int)Nc], MOD) % MOD;

        System.out.println(ans);
    }

    static long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) result = result * base % mod;
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}

