public class Main {
    static final int MOD = 1_000_000_007;
    static int[][][][] dp;
    static List<List<String>> rules;
    static boolean[][][][] computed;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int Na = sc.nextInt();
        int Nt = sc.nextInt();
        int Ng = sc.nextInt();
        int Nc = sc.nextInt();
        sc.nextLine();

        int nonTermCount = n;
        // 0 = 'A', 1 = 'T', 2 = 'G', 3 = 'C'
        rules = new ArrayList<>();
        for (int i = 0; i < nonTermCount; i++) {
            String line = sc.nextLine().trim();
            String[] parts = line.split(" ");
            List<String> prod = new ArrayList<>();
            // first part is non-terminal name, skip it
            for (int j = 1; j < parts.length; j++) {
                prod.add(parts[j]);
            }
            rules.add(prod);
        }

        dp = new int[nonTermCount][Na+1][Nt+1][Ng+1];
        computed = new boolean[nonTermCount][Na+1][Nt+1][Ng+1];
        for (int i = 0; i < nonTermCount; i++) {
            for (int a = 0; a <= Na; a++) {
                for (int t = 0; t <= Nt; t++) {
                    Arrays.fill(dp[i][a][t], -1);
                }
            }
        }

        int result = solve(0, Na, Nt, Ng, Nc);
        System.out.println(result);
        sc.close();
    }

    static int solve(int ntIdx, int a, int t, int g, int c) {
        if (a < 0 || t < 0 || g < 0 || c < 0) return 0;
        if (computed[ntIdx][a][t][g]) return dp[ntIdx][a][t][g];
        computed[ntIdx][a][t][g] = true;

        long total = 0;
        for (String prod : rules.get(ntIdx)) {
            if (prod.length() == 1) {
                // terminal
                char ch = prod.charAt(0);
                int na = a, nt = t, ng = g, nc = c;
                if (ch == 'A') na--;
                else if (ch == 'T') nt--;
                else if (ch == 'G') ng--;
                else if (ch == 'C') nc--;
                if (na == 0 && nt == 0 && ng == 0 && nc == 0) total++;
            } else {
                // two non-terminals
                int idx1 = prod.charAt(0) - 'A';
                int idx2 = prod.charAt(1) - 'A';
                for (int i = 0; i <= a; i++) {
                    for (int j = 0; j <= t; j++) {
                        for (int k = 0; k <= g; k++) {
                            for (int l = 0; l <= c; l++) {
                                long left = solve(idx1, i, j, k, l);
                                if (left == 0) continue;
                                long right = solve(idx2, a - i, t - j, g - k, c - l);
                                if (right == 0) continue;
                                total = (total + left * right) % MOD;
                            }
                        }
                    }
                }
            }
        }
        dp[ntIdx][a][t][g] = (int) total;
        return dp[ntIdx][a][t][g];
    }
}

