import java.util.*;

/*
We count strings generated by a context-free grammar over terminals {A,T,G,C},
with exact counts Na, Nt, Ng, Nc.

Input format assumed:
Na Nt Ng Nc
R
Then R rules, one per line, of the form:
X -> alpha
where X is a non-terminal (single token), and alpha is a sequence of symbols
separated by spaces or written contiguously; terminals are A,T,G,C and other
symbols are non-terminals.
The start symbol is the left-hand side of the first rule.

If multiple rules have the same LHS, they are alternatives.

The grammar is assumed acyclic/productive enough for dynamic programming by
total terminal count. We compute, for each non-terminal, the number of ways to
derive strings with given terminal counts.

Answer modulo 1e9+7.

Because the original statement fragment does not specify exact grammar input
format, this parser is made tolerant:
- "S -> A B C"
- "S->ABC"
- "S ABC"
all work reasonably if symbols are single-character or space-separated tokens.
For contiguous RHS tokens, terminals are A/T/G/C and maximal other chunks are
treated as single non-terminal names only when space-separated is absent; thus
space-separated grammar is preferred.
*/
public class Main {
    static final long MOD = 1_000_000_007L;

    static class Rule {
        int lhs;
        List<String> rhsRaw;
        int[] rhs; // encoded symbols: terminals 0..3, nonterminals 4+
        Rule(int lhs, List<String> rhsRaw) {
            this.lhs = lhs;
            this.rhsRaw = rhsRaw;
        }
    }

    static class Key {
        final int a, t, g, c;
        Key(int a, int t, int g, int c) {
            this.a = a; this.t = t; this.g = g; this.c = c;
        }
        @Override public boolean equals(Object o) {
            if (!(o instanceof Key)) return false;
            Key k = (Key)o;
            return a == k.a && t == k.t && g == k.g && c == k.c;
        }
        @Override public int hashCode() {
            int h = a;
            h = h * 239017 + t;
            h = h * 239017 + g;
            h = h * 239017 + c;
            return h;
        }
    }

    static int Na, Nt, Ng, Nc;
    static int totalLen;
    static List<Rule> rules = new ArrayList<>();
    static Map<String, Integer> ntId = new HashMap<>();
    static List<String> ntNames = new ArrayList<>();
    static List<List<Rule>> byLhs = new ArrayList<>();
    static int startNt;

    // dp[nonterminal] = map from counts to ways
    static Map<Key, Long>[] dp;

    static int getNt(String s) {
        Integer id = ntId.get(s);
        if (id != null) return id;
        int nid = ntNames.size();
        ntId.put(s, nid);
        ntNames.add(s);
        byLhs.add(new ArrayList<>());
        return nid;
    }

    static boolean isTerminal(String s) {
        return s.length() == 1 && "ATGC".indexOf(s.charAt(0)) >= 0;
    }

    static int termIndex(String s) {
        switch (s.charAt(0)) {
            case 'A': return 0;
            case 'T': return 1;
            case 'G': return 2;
            case 'C': return 3;
        }
        return -1;
    }

    static List<String> parseRhs(String rhs) {
        rhs = rhs.trim();
        if (rhs.isEmpty()) return new ArrayList<>();
        String[] sp = rhs.split("\\s+");
        if (sp.length > 1) return new ArrayList<>(Arrays.asList(sp));

        // No spaces: split terminals A/T/G/C as single chars, and other chars as single-char symbols.
        // This is a best-effort fallback.
        List<String> res = new ArrayList<>();
        for (int i = 0; i < rhs.length(); i++) {
            res.add(String.valueOf(rhs.charAt(i)));
        }
        return res;
    }

    static long addMod(long a, long b) {
        a += b;
        if (a >= MOD) a -= MOD;
        return a;
    }

    static long mulMod(long a, long b) {
        return (a * b) % MOD;
    }

    static Map<Key, Long> evalRule(Rule rule) {
        Map<Key, Long> cur = new HashMap<>();
        cur.put(new Key(0,0,0,0), 1L);

        for (int sym : rule.rhs) {
            Map<Key, Long> next = new HashMap<>();
            if (sym < 4) {
                for (Map.Entry<Key, Long> e : cur.entrySet()) {
                    Key k = e.getKey();
                    int a = k.a, t = k.t, g = k.g, c = k.c;
                    if (sym == 0) a++;
                    else if (sym == 1) t++;
                    else if (sym == 2) g++;
                    else c++;
                    if (a > Na || t > Nt || g > Ng || c > Nc) continue;
                    Key nk = new Key(a,t,g,c);
                    next.put(nk, addMod(next.getOrDefault(nk, 0L), e.getValue()));
                }
            } else {
                int nt = sym - 4;
                Map<Key, Long> sub = dp[nt];
                if (sub.isEmpty()) return Collections.emptyMap();
                for (Map.Entry<Key, Long> e1 : cur.entrySet()) {
                    Key k1 = e1.getKey();
                    long v1 = e1.getValue();
                    for (Map.Entry<Key, Long> e2 : sub.entrySet()) {
                        Key k2 = e2.getKey();
                        int a = k1.a + k2.a;
                        int t = k1.t + k2.t;
                        int g = k1.g + k2.g;
                        int c = k1.c + k2.c;
                        if (a > Na || t > Nt || g > Ng || c > Nc) continue;
                        Key nk = new Key(a,t,g,c);
                        long ways = mulMod(v1, e2.getValue());
                        next.put(nk, addMod(next.getOrDefault(nk, 0L), ways));
                    }
                }
            }
            cur = next;
            if (cur.isEmpty()) break;
        }
        return cur;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.trim().isEmpty()) lines.add(line);
        }
        if (lines.isEmpty()) return;

        int ptr = 0;
        StringTokenizer st = new StringTokenizer(lines.get(ptr++));
        Na = Integer.parseInt(st.nextToken());
        Nt = Integer.parseInt(st.nextToken());
        Ng = Integer.parseInt(st.nextToken());
        Nc = Integer.parseInt(st.nextToken());
        totalLen = Na + Nt + Ng + Nc;

        if (ptr >= lines.size()) {
            System.out.println(0);
            return;
        }

        int R;
        {
            String s = lines.get(ptr++).trim();
            R = Integer.parseInt(s);
        }

        for (int i = 0; i < R && ptr < lines.size(); i++, ptr++) {
            String s = lines.get(ptr).trim();

            String lhsStr;
            String rhsStr;

            int arrow = s.indexOf("->");
            if (arrow >= 0) {
                lhsStr = s.substring(0, arrow).trim();
                rhsStr = s.substring(arrow + 2).trim();
            } else {
                String[] parts = s.split("\\s+", 2);
                lhsStr = parts[0];
                rhsStr = parts.length > 1 ? parts[1] : "";
            }

            int lhs = getNt(lhsStr);
            if (rules.isEmpty()) startNt = lhs;

            List<String> rhs = parseRhs(rhsStr);
            Rule rule = new Rule(lhs, rhs);
            rules.add(rule);
        }

        // Register non-terminals appearing on RHS
        for (Rule r : rules) {
            for (String tok : r.rhsRaw) {
                if (!isTerminal(tok)) getNt(tok);
            }
        }

        // Encode RHS
        for (Rule r : rules) {
            r.rhs = new int[r.rhsRaw.size()];
            for (int i = 0; i < r.rhsRaw.size(); i++) {
                String tok = r.rhsRaw.get(i);
                if (isTerminal(tok)) r.rhs[i] = termIndex(tok);
                else r.rhs[i] = 4 + getNt(tok);
            }
            byLhs.get(r.lhs).add(r);
        }

        int n = ntNames.size();
        dp = new HashMap[n];
        for (int i = 0; i < n; i++) dp[i] = new HashMap<>();

        // Fixed-point iteration for general acyclic/lightly recursive grammars.
        // Since counts are bounded, state space is finite.
        boolean changed;
        do {
            changed = false;
            for (int nt = 0; nt < n; nt++) {
                Map<Key, Long> accum = new HashMap<>(dp[nt]);
                for (Rule r : byLhs.get(nt)) {
                    Map<Key, Long> got = evalRule(r);
                    for (Map.Entry<Key, Long> e : got.entrySet()) {
                        Key k = e.getKey();
                        long old = accum.getOrDefault(k, 0L);
                        long nv = addMod(old, e.getValue());
                        if (nv != old) {
                            accum.put(k, nv);
                        }
                    }
                }
                if (accum.size() != dp[nt].size()) {
                    changed = true;
                } else {
                    for (Map.Entry<Key, Long> e : accum.entrySet()) {
                        if (!Objects.equals(dp[nt].get(e.getKey()), e.getValue())) {
                            changed = true;
                            break;
                        }
                    }
                }
                dp[nt] = accum;
            }
        } while (changed);

        long ans = dp[startNt].getOrDefault(new Key(Na, Nt, Ng, Nc), 0L) % MOD;
        System.out.println(ans);
    }
}

